import java.util.Scanner;

public class JavaApplication1 {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String firstLine = sc.nextLine();
        String secondLine = sc.nextLine();
        String processed = secondLine.replaceAll("_+", " ").trim();
        StringBuilder buffer = new StringBuilder();
        int inside = 0;
        for (char ch : processed.toCharArray()) {
            if (ch == '(') {
                inside = 1;
            } else if (ch == ')') {
                buffer.append(' ');
                inside = 0;
            } else if (inside == 1) {
                buffer.append(ch);
            }
        }
        String s = secondLine;
        int pos;
        while ((pos = s.indexOf('(')) != -1) {
            int endPos = s.indexOf(')', pos);
            if (endPos == -1) break;
            s = s.substring(0, pos) + " " + s.substring(endPos + 1);
        }
        s = s.replaceAll(" +", " ").trim();
        String insideStr = buffer.toString().replaceAll(" +", " ").trim();
        String[] outArr = s.split(" ");
        String[] inArr = insideStr.split(" ");
        int maxLen = 0;
        for (String word : outArr) {
            if (word.length() > maxLen) {
                maxLen = word.length();
            }
        }
        if (!insideStr.isEmpty()) {
            System.out.println(maxLen + " " + inArr.length);
        } else {
            System.out.println(maxLen + " 0");
        }
    }
}
